function sequence(options) {
  return options.reduce((acc, opt) => {
    if (acc.tag === 'None' || opt.tag === 'None') return { tag: 'None' };
    return { tag: 'Some', value: [...acc.value, opt.value] };
  }, { tag: 'Some', value: [] });
}

const allValid = [{ tag: 'Some', value: 10 }, { tag: 'Some', value: 20 }];
const hasInvalid = [{ tag: 'Some', value: 10 }, { tag: 'None' }, { tag: 'Some', value: 30 }];

console.log(sequence(allValid));
console.log(sequence(hasInvalid));

